# Check that key imports are consistent
import ast, os

imports = {}
for root, dirs, files in os.walk('.'):
    for f in files:
        if f.endswith('.py'):
            path = os.path.join(root, f)
            with open(path) as fh:
                source = fh.read()
            tree = ast.parse(source)
            for node in ast.walk(tree):
                if isinstance(node, ast.Import):
                    for alias in node.names:
                        name = alias.name.split('.')[0]
                        if name not in imports:
                            imports[name] = []
                        imports[name].append(path)
                elif isinstance(node, ast.ImportFrom):
                    if node.module:
                        name = node.module.split('.')[0]
                        if name not in imports:
                            imports[name] = []
                        imports[name].append(path)

# Check internal imports
internal_modules = ['luno', 'experiments', 'data_generation']
for mod in internal_modules:
    if mod in imports:
        print(f'{mod}: imported by {len(set(imports[mod]))} files')
    else:
        print(f'{mod}: NOT imported anywhere (may be standalone)')

print()
print('External imports:')
for name, files in sorted(imports.items()):
    if name not in internal_modules:
        print(f'  {name} (in {len(set(files))} files)')
